# claims whose numbers were recomputed after the code review of 2026-09-28 (p95 rev 6, p95e rev 2); their statements were rewritten
# on the maintainer's direction of 2026-09-29 (rev-6 numbers, support classes, the withheld gauge, the baseline-connectivity mechanism)
REVIEW_PENDING = {c: "TABLES_LINKED; RECOMPUTED 2026-09-30 in the vertical frame of Paper 1 v6 (p95 rev 7 / p95e rev 2); statement revised on the maintainer's direction 2026-09-29" for c in ("C01", "C02", "C03", "C07")}
REVIEW_PENDING["C14"] = "TABLES_LINKED; RECOMPUTED 2026-09-30 (pool levels in Paper 1's frame, Nikopol bound, G-REALM a check only; Sentinel-2 exposure)"
# stage 2 of the review (F09-F11): the numbers of C09-C11 are the frozen v002 / v003_A single-seed arms; the same comparisons were
# re-run on the corrected labels (v002_notrace / v004) with three training seeds -- statements pending the maintainer's review
REVIEW_PENDING.update({                                                   # statements decided by the maintainer on 2026-09-29 (Stage 2 closure)
    "C09": "TABLES_LINKED; statement decided by the maintainer 2026-09-29 (D-C09)",
    "C10": "TABLES_LINKED; statement decided by the maintainer 2026-09-29 (D-C10: retracted, negative result); the U1 sentence from T06s (three seeds)",
    "C11": "TABLES_LINKED; statement decided by the maintainer 2026-09-29 (D-C11)",
    "C12": "TABLES_LINKED; RECOMPUTED 2026-09-29 on RF20 rev 2 (F08); wording D-RF20 (maintainer 2026-09-29)",
    "C13": "TABLES_LINKED; narrowed in the text pass 2026-09-29",
    "C08": "TABLES_LINKED; text pass 2026-09-29 (v004, three seeds; reconstructed rows = Monte-Carlo medians)"})


def main():
    M = pd.read_csv(PUB / "evidence_matrix.csv").fillna("")
    for cid, f in FILL.items():
        for k, v in f.items():
            M.loc[M.claim_id == cid, k] = PAT.sub(resolve, v)
        M.loc[M.claim_id == cid, "validation_status"] = "TABLES_LINKED" if cid not in REVIEW_PENDING else REVIEW_PENDING[cid]
    M.to_csv(PUB / "evidence_matrix.csv", index=False)
    miss = [(cid, k) for cid in FILL for k in ("n", "value", "uncertainty") if "[[MISSING" in str(M.loc[M.claim_id == cid, k].iloc[0])]
    print("evidence matrix filled;", "unresolved:", miss if miss else "none")


if __name__ == "__main__":
    main()
